window.PET_PROFESSIONALS_SEARCH_INDEX = [{"path": "index.html", "html": "<!DOCTYPE html>\n<html lang=\"en\">\n    <head>\n        <meta charset=\"UTF-8\">\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n        <title>Home | Visit Taniti</title>\n        <link rel=\"stylesheet\" href=\"style.css\">\n    </head>\n    <body class=\"home\">\n        <header>\n            <h1><img class=\"left\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\">Come Visit Taniti!<img class=\"right\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\"></h1>\n            <nav>\n                <ul class=\"nav-bar header-nav\">\n                    <li class=\"active\"><a href=\"index.html\">Home</a></li>\n                    <li class=\"inactive\"><a href=\"Accommodations.html\">Accommodations</a></li>\n                    <li class=\"inactive\"><a href=\"ThingsToDo.html\">Things To Do</a></li>\n                    <li class=\"inactive\"><a href=\"Dining.html\">Dining</a></li>\n                    <li class=\"inactive\"><a href=\"Transportation.html\">Transportation</a></li>\n                    <li class=\"inactive\"><a href=\"FAQs.html\">FAQs</a></li>\n                </ul>\n                <form class=\"search-bar header-search\" role=\"search\">\n                    <label class=\"visually-hidden\" for=\"site-search\">Search this site</label>\n                    <input id=\"site-search\" type=\"search\" name=\"q\" placeholder=\"Search...\" aria-label=\"Search this site\">\n                    <button type=\"submit\">Search</button>\n                    <span class=\"search-status visually-hidden\" aria-live=\"polite\"></span>\n                </form>\n            </nav>\n        </header>\n        <main class=\"main-aside\">\n            <div class=\"home-content\">\n                <h2>Taniti: Where Adventure Awaits</h2>\n                <p>Welcome to Taniti, a tropical paradise with something for everyone!</p>\n                <p>Whether you're seeking relaxation on pristine beaches, thrilling outdoor adventures, or a taste of local culture and cuisine, Taniti has it all. Explore our diverse accommodations, indulge in delicious dining options, and discover the many activities that make Taniti a must-visit destination.</p>\n                <p>Plan your trip today and experience the magic of Taniti!</p>\n                <img src=\"/media/people-having-fun.jpg\" alt=\"People Having Fun\">\n            </div>\n            <div class=\"aside\">\n                <h3>Taniti at a Glance</h3>\n                <ul>\n                    <li>Hikes in the rainforest</li>\n                    <li>Luxurious 4 star family resort</li>\n                    <li>Beautiful Beaches</li>\n                    <li>World class dining</li>\n                    <li>And much, much more!</li>\n                </ul>\n            </div>\n        </main>\n        <footer>\n            <p>Your Adventure Awaits!</p>\n        </footer>\n        <script src=\"search-index.js?v=7\"></script>\n        <script src=\"search.js?v=8\"></script>\n    </body>\n</html>\n"}, {"path": "Accommodations.html", "html": "<!DOCTYPE html>\n<html lang=\"en\">\n    <head>\n        <meta charset=\"UTF-8\">\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n        <title>Accommodations | Visit Taniti</title>\n        <link rel=\"stylesheet\" href=\"style.css\">\n    </head>\n    <body class=\"home\">\n        <header>\n            <h1><img class=\"left\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\">Accommodations<img class=\"right\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\"></h1>\n            <nav>\n                <ul class=\"nav-bar header-nav\">\n                    <li class=\"inactive\"><a href=\"index.html\">Home</a></li>\n                    <li class=\"active\"><a href=\"Accommodations.html\">Accommodations</a></li>\n                    <li class=\"inactive\"><a href=\"ThingsToDo.html\">Things To Do</a></li>\n                    <li class=\"inactive\"><a href=\"Dining.html\">Dining</a></li>\n                    <li class=\"inactive\"><a href=\"Transportation.html\">Transportation</a></li>\n                    <li class=\"inactive\"><a href=\"FAQs.html\">FAQs</a></li>\n                </ul>\n                <form class=\"search-bar header-search\" role=\"search\">\n                    <label class=\"visually-hidden\" for=\"site-search\">Search this site</label>\n                    <input id=\"site-search\" type=\"search\" name=\"q\" placeholder=\"Search...\" aria-label=\"Search this site\">\n                    <button type=\"submit\">Search</button>\n                    <span class=\"search-status visually-hidden\" aria-live=\"polite\"></span>\n                </form>\n            </nav>\n        </header>\n        <main>\n            <p class=\"intro\">Taniti has a variety of accomodations to suit every traveller! From cozy hostels to luxury resorts, we have something for everyone.</p>\n            <div class=\"collage\">\n                <div class=\"hostel\">\n                    <div class=\"accomodation-links\">\n                        <h2>Moana Lodge</h2>\n                        <p>A cozy hostel in the north side of the island, this is an affordable option for the people loving adventurer.</p>\n                            <p>$52/night</p>\n                            <p>Free Wifi</p>\n                            <p>Air Conditioning</p>\n                        <p>Booking: <a href=\"othersite.html\">Moana Lodge Booking</a></p>\n                    </div>\n                </div>\n                <div class=\"resort\">\n                    <div class=\"accomodation-links\">\n                        <h2>Taniti Diamond Resort</h2>\n                        <p>A four-star beachside resort for fun and relaxation for the whole family!</p>\n                            <p>Infinity Pool</p>\n                            <p>Day Spa</p>\n                            <p>Health Club</p>\n                        <p>Booking: <a href=\"othersite.html\">Taniti Diamond Booking</a></p>\n                    </div>\n                </div>\n                <div class=\"hotel\">\n                    <div class=\"accomodation-links\">\n                        <h2>Hotels</h2>\n                        <p>Taniti offers a variety of small family owned hotels!</p>\n                            <p>Booking: <a href=\"othersite.html\">Mateva Booking</a></p>\n                            <p>Booking: <a href=\"othersite.html\">Aha Hotel Booking</a></p>\n                            <p>Booking: <a href=\"othersite.html\">Antui Lodge Booking</a></p>\n                            <p>Booking: <a href=\"othersite.html\">Ontonui Studio Booking</a></p>    \n                    </div>\n                </div>\n                    <div class=\"bnb\">\n                        <div class=\"bnb-type\">\n                            <div class=\"accomodation-links\">\n                                <h2>Bed and Breakfasts</h2>\n                                <p>If you  seek the Taniti experience, but still want the comforts of home, Taniti offers many bed and breakfasts.</p>\n                                <p>To find your home away from home: <a href=\"othersite.html\">AirBnB.com</a></p>\n                            </div>\n                        </div>\n                    </div>\n            </div>\n        </main>\n        <footer>\n            <p>Your Adventure Awaits!</p>\n        </footer>\n        <script src=\"search-index.js?v=7\"></script>\n        <script src=\"search.js?v=8\"></script>\n    </body>\n</html>"}, {"path": "ThingsToDo.html", "html": "<!DOCTYPE html>\n<html lang=\"en\">\n    <head>\n        <meta charset=\"UTF-8\">\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n        <title>Things To Do | Visit Taniti</title>\n        <link rel=\"stylesheet\" href=\"style.css\">\n    </head>\n    <body class=\"home\">\n        <header>\n            <h1><img class=\"left\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\">Things To Do<img class=\"right\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\"></h1>\n            <nav>\n                <ul class=\"nav-bar header-nav\">\n                    <li class=\"inactive\"><a href=\"index.html\">Home</a></li>\n                    <li class=\"inactive\"><a href=\"Accommodations.html\">Accommodations</a></li>\n                    <li class=\"active\"><a href=\"ThingsToDo.html\">Things To Do</a></li>\n                    <li class=\"inactive\"><a href=\"Dining.html\">Dining</a></li>\n                    <li class=\"inactive\"><a href=\"Transportation.html\">Transportation</a></li>\n                    <li class=\"inactive\"><a href=\"FAQs.html\">FAQs</a></li>\n                </ul>\n                <form class=\"search-bar header-search\" role=\"search\">\n                    <label class=\"visually-hidden\" for=\"site-search\">Search this site</label>\n                    <input id=\"site-search\" type=\"search\" name=\"q\" placeholder=\"Search...\" aria-label=\"Search this site\">\n                    <button type=\"submit\">Search</button>\n                    <span class=\"search-status visually-hidden\" aria-live=\"polite\"></span>\n                </form>\n            </nav>\n        </header>\n        <main>\n            <p class=\"intro\">Explore the best things to do in Taniti! From natural wonders to bustling cities, we have something for every type of traveller.</p>\n            <div class=\"collage\">\n                <a class=\"city\" href=\"CityFun.html\">\n                <img src=\"media/city.png\" alt=\"People Having Fun in the City\">\n                <div class=\"card-overlay\">\n                    <h2>Fun in the City</h2>\n                    <p>If the hustle and bustle of city life is what gets your heart pumping, Taniti has anythiing you could be looking for. From the excitement of our night life, to educational adventures, to theatres and arcades, Taniti has it all.</p>\n                    <p>Click to Learn More!</p>\n                </div>\n                </a>\n                <a class=\"city\" href=\"NatureFun.html\">\n                <img src=\"media/outside.png\" alt=\"People Having Fun at the Beach\">\n                <div class=\"card-overlay\">\n                    <h2>For the Nature Explorer</h2>\n                    <p>For those of you that want to get away to the great outdoors, Taniti is just the place. Unleash your inner explorer in the lush rainforests, get wet and wild at the beach, or turn up the heat by visiting Taniti's volcano.</p>\n                    <p>Click to Learn More!</p>\n                </div>\n                </a>\n                </div>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </main>\n        <footer>\n            <p>Your Adventure Awaits!</p>\n        </footer>\n        <script src=\"search-index.js?v=7\"></script>\n        <script src=\"search.js?v=8\"></script>\n    </body>\n</html>\n"}, {"path": "Dining.html", "html": "<!DOCTYPE html>\n<html lang=\"en\">\n    <head>\n        <meta charset=\"UTF-8\">\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n        <title>Dining | Visit Taniti</title>\n        <link rel=\"stylesheet\" href=\"style.css\">\n    </head>\n    <body class=\"home\">\n        <header>\n            <h1><img class=\"left\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\">Dining<img class=\"right\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\"></h1>\n            <nav>\n                <ul class=\"nav-bar header-nav\">\n                    <li class=\"inactive\"><a href=\"index.html\">Home</a></li>\n                    <li class=\"inactive\"><a href=\"Accommodations.html\">Accommodations</a></li>\n                    <li class=\"inactive\"><a href=\"ThingsToDo.html\">Things To Do</a></li>\n                    <li class=\"active\"><a href=\"Dining.html\">Dining</a></li>\n                    <li class=\"inactive\"><a href=\"Transportation.html\">Transportation</a></li>\n                    <li class=\"inactive\"><a href=\"FAQs.html\">FAQs</a></li>\n                </ul>\n                <form class=\"search-bar header-search\" role=\"search\">\n                    <label class=\"visually-hidden\" for=\"site-search\">Search this site</label>\n                    <input id=\"site-search\" type=\"search\" name=\"q\" placeholder=\"Search...\" aria-label=\"Search this site\">\n                    <button type=\"submit\">Search</button>\n                    <span class=\"search-status visually-hidden\" aria-live=\"polite\"></span>\n                </form>\n            </nav>\n        </header>\n        <main>\n   <div>\n            <p class=\"intro\">For the foodies! Taniti has wonderful dining experiences for everyone.</p>\n            <div class=\"dining-collage-top\">\n                <div class=\"restaurant1\">\n                    <div class=\"accomodation-links\">\n                        <p class=\"bigger-font\">Surfs Up Taniti</p>\n                        <p>Serving lcoal seafood in a pacific island style.</p>\n                        <p><a href=\"othersite.html\">Menu</a></p>\n                        <p><a href=\"othersite.html\">Maps</a></p>\n                    </div>\n                </div>\n                <div class=\"restaurant2\">\n                    <div class=\"accomodation-links\">\n                        <p class=\"bigger-font\">The Cherry Blossom</p>\n                        <p>Authentic Tanitian food in a high class enviroment.</p>\n                        <p><a href=\"othersite.html\">Menu</a></p>\n                        <p><a href=\"othersite.html\">Maps</a></p>\n                    </div>\n                </div>\n                <div class=\"restaurant3\">\n                    <div class=\"accomodation-links\">\n                        <p class=\"bigger-font\">Red Guava</p>\n                        <p>Bold seafood and bar.</p>\n                        <p><a href=\"othersite.html\">Menu</a></p>\n                        <p><a href=\"othersite.html\">Maps</a></p>     \n                    </div>\n                </div>\n                <div class=\"restaurant4\">\n                    <div class=\"accomodation-links\">\n                        <p class=\"bigger-font\">Le Solara</p>\n                        <p>Outdoor grill with pizzaz.</p>\n                        <p><a href=\"othersite.html\">Menu</a></p>\n                        <p><a href=\"othersite.html\">Maps</a></p>\n                    </div>\n                </div>\n                 <div class=\"restaurant5\">\n                    <div class=\"accomodation-links\">\n                        <p class=\"bigger-font\">Le Huei</p>\n                        <p>Fine dining and local cuisine.</p>\n                        <p><a href=\"othersite.html\">Menu</a></p>\n                        <p><a href=\"othersite.html\">Maps</a></p>\n                    </div>\n                </div>\n                <div class=\"restaurant6\">\n                    <div class=\"accomodation-links\">\n                        <p class=\"bigger-font\">Taniti Steet</p>\n                        <p>American style burgers and pizza.</p>\n                        <p><a href=\"othersite.html\">Menu</a></p>\n                        <p><a href=\"othersite.html\">Maps</a></p>\n                    </div>\n                </div>\n            </div>\n            <div class=\"dining-collage-bottom\">\n                <div class=\"restaurant7\">\n                    <div class=\"accomodation-links\">\n                        <p class=\"bigger-font\">Le Grille</p>\n                        <p>American style barbecue.</p>\n                        <p><a href=\"othersite.html\">Menu</a></p>\n                        <p><a href=\"othersite.html\">Maps</a></p>      \n                    </div>\n                </div>\n                <div class=\"stores\">\n                        <p>Shopping</p>\n                       <p>Taniti offers two super markets and one convienience store that is open 24/7</p>\n                        <p>Darrethree: <a href=\"othersite.html\">Maps</a></p>\n                        <p>Winner's Circle: <a href=\"othersite.html\">Maps</a></p>\n                        <p>Super Y: <a href=\"othersite.html\">Maps</a></p>\n                </div>\n                </div>\n            </div>\n        </main>\n        <footer>\n            <p>Your Adventure Awaits!</p>\n        </footer>\n        <script src=\"search-index.js?v=7\"></script>\n        <script src=\"search.js?v=8\"></script>\n    </body>\n</html>"}, {"path": "Transportation.html", "html": "<!DOCTYPE html>\n<html lang=\"en\">\n    <head>\n        <meta charset=\"UTF-8\">\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n        <title>Transportation | Visit Taniti</title>\n        <link rel=\"stylesheet\" href=\"style.css\">\n    </head>\n    <body class=\"home\">\n        <header>\n            <h1><img class=\"left\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\">Transportation<img class=\"right\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\"></h1>\n            <nav>\n                <ul class=\"nav-bar header-nav\">\n                    <li class=\"inactive\"><a href=\"index.html\">Home</a></li>\n                    <li class=\"inactive\"><a href=\"Accommodations.html\">Accommodations</a></li>\n                    <li class=\"inactive\"><a href=\"ThingsToDo.html\">Things To Do</a></li>\n                    <li class=\"inactive\"><a href=\"Dining.html\">Dining</a></li>\n                    <li class=\"active\"><a href=\"Transportation.html\">Transportation</a></li>\n                    <li class=\"inactive\"><a href=\"FAQs.html\">FAQs</a></li>\n                </ul>\n                <form class=\"search-bar header-search\" role=\"search\">\n                    <label class=\"visually-hidden\" for=\"site-search\">Search this site</label>\n                    <input id=\"site-search\" type=\"search\" name=\"q\" placeholder=\"Search...\" aria-label=\"Search this site\">\n                    <button type=\"submit\">Search</button>\n                    <span class=\"search-status visually-hidden\" aria-live=\"polite\"></span>\n                </form>\n            </nav>\n        </header>\n        <main>\n            <p class=\"intro\">Whether traveling by land, sea, or air, Taniti has it all. Book your trip today!</p>\n            <div class=\"transportation-list\">\n                <div class=\"restaurant1\" id=\"small-airport\">\n                    <div class=\"accomodation-links\">\n                        <h2>Airport</h2>\n                        <p>Fly in syle at our local airport. Tickets at an <a href=\"othersite.html\">affordable price</a> whenever you need them.</p>\n                    </div>\n                </div>\n                <div class=\"restaurant2\" id=\"cruise-ship\">\n                    <div class=\"accomodation-links\">\n                        <h2>Cruise Ship</h2>\n                        <p>They say the key to life is enjoying the journey, and that has never been more applicable than with our <a href=\"othersite.html\">luxury cruise liner.</a> Fun for the whole family, enjoy the high seas on your way to paradise.</p>\n                    </div>\n                </div>\n                <div class=\"restaurant3\" id=\"public-buses\">\n                    <div class=\"accomodation-links\">\n                        <h2>Public Buses</h2>\n                        <p>While most everything on the island is easily accesible on foot, there is no need to walk thanks to our <a href=\"othersite.html\">public bus system.</a></p>\n                    </div>    \n                </div>\n                <div class=\"restaurant4\" id=\"private-buses\">\n                    <div class=\"accomodation-links\">\n                        <h2>Private Buses</h2>\n                        <p>Where the public bus system doesn't go, a <a href=\"othersite.html\">private bus</a> will. Book transportation for your next event today!</p>\n                </div>\n                </div>\n                 <div class=\"restaurant5\" id=\"taxi\">\n                    <div class=\"accomodation-links\">\n                        <h2>Taxis</h2>\n                        <p>If buses aren't your style, you can always call one of our adorarable <a href=\"othersite.html\">little taxis!</a> Always a tourist favorite.</p>\n                    </div>\n                </div>\n                <div class=\"restaurant6\" id=\"large-airport\">\n                    <div class=\"accomodation-links\">\n                        <h2>Coming Soon</h2>\n                        <p>A large international airport is planned to be finished next year.</p>\n                    </div>\n                </div>\n            </div>\n        </main>\n        <footer>\n            <p>Your Adventure Awaits!</p>\n        </footer>\n        <script src=\"search-index.js?v=7\"></script>\n        <script src=\"search.js?v=8\"></script>\n    </body>\n</html>\n"}, {"path": "FAQs.html", "html": "<!DOCTYPE html>\n<html lang=\"en\">\n    <head>\n        <meta charset=\"UTF-8\">\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n        <title>Frequently Asked Questions | Visit Taniti</title>\n        <link rel=\"stylesheet\" href=\"style.css\">\n    </head>\n    <body class=\"home\">\n        <header>\n            <h1><img class=\"left\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\">FAQs<img class=\"right\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\"></h1>\n            <nav>\n                <ul class=\"nav-bar header-nav\">\n                    <li class=\"inactive\"><a href=\"index.html\">Home</a></li>\n                    <li class=\"inactive\"><a href=\"Accommodations.html\">Accommodations</a></li>\n                    <li class=\"inactive\"><a href=\"ThingsToDo.html\">Things To Do</a></li>\n                    <li class=\"inactive\"><a href=\"Dining.html\">Dining</a></li>\n                    <li class=\"inactive\"><a href=\"Transportation.html\">Transportation</a></li>\n                    <li class=\"active\"><a href=\"FAQs.html\">FAQs</a></li>\n                </ul>\n                <form class=\"search-bar header-search\" role=\"search\">\n                    <label class=\"visually-hidden\" for=\"site-search\">Search this site</label>\n                    <input id=\"site-search\" type=\"search\" name=\"q\" placeholder=\"Search...\" aria-label=\"Search this site\">\n                    <button type=\"submit\">Search</button>\n                    <span class=\"search-status visually-hidden\" aria-live=\"polite\"></span>\n                </form>\n            </nav>\n        </header>\n        <main class=\"main-aside\">\n            <div class=\"home-content faq-intro\">\n                <h2>Frequently Asked Questions</h2>\n                <p><b>What kind of chager do I need?</b></p>\n                <p>Taniti utilizes 120 volt outlets, the same as the United States.</p>\n                <p><b>What are the laws regarding alohol?</b></p>\n                <p>Alcohol is not allowed to be served or sold between the hours of midnight and 9:00 a.m. \n                The drinking age on Taniti is 18 and the drinking age is not strictly enforced.</p>\n                <p><b>Does anyone speak English?</b></p>\n                <p>Many younger Tanitians speak fluent English. Very little English is spoken in rural areas, especially by the older residents.</p>\n                <p><b>What if I have a medical emergency?</b></p>\n                <p>There is one hospital and several clinics. The hospital has many multilingual employees.</p>\n                <p><b>Should I be worried about crime?</b></p>\n                <p>Violent crime is very rare on Taniti, but as tourism increases, there are more reports of pickpocketing and other petty crimes. </p>\n                <p><b>Do buisinesses close on national holidays?</b></p>\n                <p>Taniti enjoys a large number of national holidays, and many tourist attractions and restaurants will be closed on holidays, so visitors should plan accordingly.</p>\n                <p><b>What currency do I bring and do I need cash?</b></p>\n                <p>Taniti uses the U.S. dollar as its currency, but many businesses will also accept euros and yen. Several banks facilitate currency exchange, and many businesses accept major credit cards.\n                </p>\n            </div>\n            <section id=\"contact-form\" class=\"contact-form\" aria-labelledby=\"contact-heading\">\n                <h2 id=\"contact-heading\">Contact Us</h2>\n                <p>Have a question about visiting Taniti? Send our visitor information team a message.</p>\n                <form>\n                    <div class=\"form-field\">\n                        <label for=\"contact-name\">Name</label>\n                        <input id=\"contact-name\" name=\"name\" type=\"text\" autocomplete=\"name\" required>\n                    </div>\n                    <div class=\"form-field\">\n                        <label for=\"contact-email\">Email</label>\n                        <input id=\"contact-email\" name=\"email\" type=\"email\" autocomplete=\"email\" required>\n                    </div>\n                    <div class=\"form-field\">\n                        <label for=\"contact-subject\">What can we help with?</label>\n                        <select id=\"contact-subject\" name=\"subject\" required>\n                            <option value=\"\" selected disabled>Select a topic</option>\n                            <option value=\"accommodations\">Accommodations</option>\n                            <option value=\"activities\">Things to do</option>\n                            <option value=\"transportation\">Getting around</option>\n                            <option value=\"other\">Something else</option>\n                        </select>\n                    </div>\n                    <div class=\"form-field\">\n                        <label for=\"contact-message\">Message</label>\n                        <textarea id=\"contact-message\" name=\"message\" rows=\"6\" required></textarea>\n                    </div>\n                    <p class=\"form-note\">This form is a design preview and is not connected to a message service yet.</p>\n                    <button class=\"contact-submit\" type=\"submit\" disabled>Sending isn't set up yet</button>\n                </form>\n            </section>\n        </main>\n        <footer>\n            <p>Your Adventure Awaits!</p>\n        </footer>\n        <script src=\"search-index.js?v=7\"></script>\n        <script src=\"search.js?v=8\"></script>\n    </body>\n</html>\n"}, {"path": "NatureFun.html", "html": "<!DOCTYPE html>\n<html lang=\"en\">\n    <head>\n        <meta charset=\"UTF-8\">\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n        <title>Nature Fun | Visit Taniti</title>\n        <link rel=\"stylesheet\" href=\"style.css\">\n    </head>\n    <body class=\"home\">\n        <header>\n            <h1><img class=\"left\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\">Nature Fun<img class=\"right\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\"></h1>\n            <nav>\n                <ul class=\"nav-bar header-nav\">\n                    <li class=\"inactive\"><a href=\"index.html\">Home</a></li>\n                    <li class=\"inactive\"><a href=\"Accommodations.html\">Accommodations</a></li>\n                    <li class=\"inactive\"><a href=\"ThingsToDo.html\">Things To Do</a></li>\n                    <li class=\"inactive\"><a href=\"Dining.html\">Dining</a></li>\n                    <li class=\"inactive\"><a href=\"Transportation.html\">Transportation</a></li>\n                    <li class=\"inactive\"><a href=\"FAQs.html\">FAQs</a></li>\n                </ul>\n                <form class=\"search-bar header-search\" role=\"search\">\n                    <label class=\"visually-hidden\" for=\"site-search\">Search this site</label>\n                    <input id=\"site-search\" type=\"search\" name=\"q\" placeholder=\"Search...\" aria-label=\"Search this site\">\n                    <button type=\"submit\">Search</button>\n                    <span class=\"search-status visually-hidden\" aria-live=\"polite\"></span>\n                </form>\n            </nav>\n        </header>\n        <main>\n            <p class=\"intro\">No one's outdoors are quite as \"great\" as Taniti's!</p>\n            <div class=\"row\">\n                <div class=\"beach\">\n                    <h2>Have Fun at the Beach</h2>\n                    <p>Relax in the sand, or go <a href=\"othersite.html\">snorkeling</a> at the beach.</p>\n                </div>\n                <div class=\"rainforest\">\n                    <h2>Explore the Rainforest</h2>\n                    <p>Book a <a href=\"othersite.html\">guided hike through the rainforest</a> or go it alone.</p>  \n                </div>\n                <div class=\"volcano\">\n                    <h2>Visit the Volcano</h2>\n                    <p>Take a <a href=\"othersite.html\">guided hike</a> up to the top of the volcano.</p>\n                </div>\n            </div>\n        </main>\n        <footer>\n            <p>Your Adventure Awaits!</p>\n        </footer>\n        <script src=\"search-index.js?v=7\"></script>\n        <script src=\"search.js?v=8\"></script>\n    </body>\n</html>\n"}, {"path": "CityFun.html", "html": "<!DOCTYPE html>\n<html lang=\"en\">\n    <head>\n        <meta charset=\"UTF-8\">\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n        <title>City Fun | Visit Taniti</title>\n        <link rel=\"stylesheet\" href=\"style.css\">\n    </head>\n    <body class=\"home\">\n        <header>\n            <h1><img class=\"left\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\">City Fun<img class=\"right\" src=\"/media/palmtree-logo.png\" alt=\"Taniti Logo\" class=\"logo\"></h1>\n            <nav>\n                <ul class=\"nav-bar header-nav\">\n                    <li class=\"inactive\"><a href=\"index.html\">Home</a></li>\n                    <li class=\"inactive\"><a href=\"Accommodations.html\">Accommodations</a></li>\n                    <li class=\"inactive\"><a href=\"ThingsToDo.html\">Things To Do</a></li>\n                    <li class=\"inactive\"><a href=\"Dining.html\">Dining</a></li>\n                    <li class=\"inactive\"><a href=\"Transportation.html\">Transportation</a></li>\n                    <li class=\"inactive\"><a href=\"FAQs.html\">FAQs</a></li>\n                </ul>\n                <form class=\"search-bar header-search\" role=\"search\">\n                    <label class=\"visually-hidden\" for=\"site-search\">Search this site</label>\n                    <input id=\"site-search\" type=\"search\" name=\"q\" placeholder=\"Search...\" aria-label=\"Search this site\">\n                    <button type=\"submit\">Search</button>\n                    <span class=\"search-status visually-hidden\" aria-live=\"polite\"></span>\n                </form>\n            </nav>\n        </header>\n        <main>\n            <p class=\"intro\">So many options, so little time! Taniti's city has so much to do the question isn't what to do, but what to choose?</p>\n            <div class=\"collage\">\n                <a class=\"city\" href=\"othersite.html\">\n                <img src=\"media/museum.jpeg\" alt=\"Museum\">\n                 <div class=\"card-overlay\">\n                    <h2>Museum</h2>\n                    <p>Learn more about Taniti's history and culture by visiting the museum.</p>\n                    <p>Click to Learn More!</p>\n                </div>\n                </a>\n                <a class=\"city\" href=\"othersite.html\">\n                <img src=\"media/helicopter.jpeg\" alt=\"Helicopter Tour\">\n                 <div class=\"card-overlay\">\n                    <h2>Helicopter Tours</h2>\n                    <p>Get a birds eye view of the island with a helicopter tour.</p>\n                    <p>Click to Learn More!</p>\n                </div>\n                </a>\n                <a class=\"city\" href=\"othersite.html\">\n                <img src=\"media/pub.jpeg\" alt=\"Pub\">\n                 <div class=\"card-overlay\">\n                    <h2>Visit a Pub</h2>\n                    <p>Relax and unwind at a local pub or brewery.</p>\n                    <p>Click to Learn More!</p>\n                </div>\n                </a>\n                <a class=\"city\" href=\"othersite.html\">\n                <img src=\"media/arcade.jpeg\" alt=\"Arcade\">\n                 <div class=\"card-overlay\">\n                    <h2>Arcade</h2>\n                    <p>Get your game on at the local arcade.</p>\n                    <p>Click to Learn More!</p>\n                </div>\n                </a>\n                <a class=\"city\" href=\"othersite.html\">\n                <img src=\"media/nightclub.jpeg\" alt=\"Nightclub\">\n                 <div class=\"card-overlay\">\n                    <h2>Nightclub</h2>\n                    <p>Enjoy excitement, fun, and dancing at the nightclub.</p>\n                    <p>Click to Learn More!</p>\n                </div>\n                </a>\n                <a class=\"city\" href=\"othersite.html\">\n                <img src=\"media/theatre.jpeg\" alt=\"Theatre\">\n                 <div class=\"card-overlay\">\n                    <h2>Movie Theatre</h2>\n                    <p>Catch a flick with the family at the local movie theatre.</p>\n                    <p>Click to Learn More!</p>\n                </div>\n                </a>\n                <a class=\"city\" href=\"othersite.html\">\n                <img src=\"media/bus.jpeg\" alt=\"Bus Tours\">\n                 <div class=\"card-overlay\">\n                    <h2>Guided Bus Tours</h2>\n                    <p>Explore and learn about the city with a guided bus tour.</p>\n                    <p>Click to Learn More!</p>\n                </div>\n                </a>\n                <a class=\"city\" href=\"othersite.html\">\n                <img src=\"media/golfcourse.jpeg\" alt=\"Golf Course\">\n                <span>9 Hole Golf Course Coming Soon!</span>\n                </a>\n                </div>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </main>\n        <footer>\n            <p>Your Adventure Awaits!</p>\n        </footer>\n        <script src=\"search-index.js?v=7\"></script>\n        <script src=\"search.js?v=8\"></script>\n    </body>\n</html>"}];
